internal object DuaUkDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("Притулок від зла моїх справ", "О Аллах, я вдаюся до Тебе від зла того, що я зробив, і від зла того, чого я не зробив.", "Дуа Пророка ﷺ, згідно з Айшею (RA).", "Захист від наслідків як зробленого, так і незробленого."),
        "dua_jahdil_bala" to DuaText("Притулок від тяжких випробувань", "О Аллах, я шукаю притулку в Тебе від важких випробувань, від того, щоб мене охопили нещастя, від злих постанов і від злорадства ворогів.", "Притулок від тяжких випробувань і зловтіхи ворогів.", "Пророк ﷺ шукав притулку від цих чотирьох речей."),
        "dua_fitnat_ghina_faqr" to DuaText("Притулок від випробувань багатства та бідності", "О Аллах, я шукаю притулку в Тебе від лінощів і старості, від гріха і боргів, від випробування і покарання могили, від випробування і покарання вогню, від зла випробування багатством і від випробування бідністю.", "Притулок від випробувань могили, пекла, багатства та бідності (частина дуа).", "Повна дуа притулку від Пророка ﷺ."),
        "dua_kufr_faqr" to DuaText("Притулок від зневіри та бідності", "О Аллах, я шукаю притулку в Тебе від невір'я і бідності, і я шукаю притулку в Тебе від кари могили. Немає Бога, крім Тебе.", "Тричі вранці і ввечері.", "Абу Бакра (RA) чув, як Пророк ﷺ сказав це."),
        "dua_sharri_sami" to DuaText("Притулок від зла моїх почуттів", "О Аллах, я вдаюся до Тебе від зла мого слуху, зла мого зору, зла мого язика, зла мого серця і зла мого бажання.", "Навчав Шакаля ібн Хумайда (RA).", "Дуа для захисту кінцівок і себе від гріха."),
        "dua_hadm_gharaq" to DuaText("Притулок від раптової смерті та нещасних випадків", "О Аллах, я шукаю притулку в Тебе від розчавлення (будівлею), від падіння з висоти, від утоплення, опіків і старості; від того, що шайтан зводить мене зі шляху під час смерті, від смерті під час втечі від Твого шляху та від смерті від (отруйного) жала.", "Притулок від нещасних випадків і поганої смерті.", "Дуа притулку від Пророка ﷺ."),
        "dua_ju_khiyanah" to DuaText("Притулок від голоду і зради", "О Аллах, я шукаю притулку в Тебе від голоду, тому що він є злим супутником, і я шукаю притулку в Тебе від зради, тому що він є злим довіреним.", "Притулок від голоду і зради.", "Дуа притулку від Пророка ﷺ."),
        "dua_huda_tuqa" to DuaText("Керівництво, благочестя, цнотливість і достатність", "О Аллах, я прошу Тебе про керівництво, благочестя, цнотливість і самодостатність.", "Коротка, вичерпна дуа Пророка ﷺ.", "Чотири основні благословення релігії та цього світу."),
        "dua_aslih_li_dini" to DuaText("Виправте мою релігію, світ і майбутнє", "О Аллах, виправи мою релігію, яка є захистом усіх моїх справ; виправити моє мирське життя, в якому є мій засіб до існування; і впорядкуй мій світ, до якого я повернуся. Зроби, щоб життя примножилося для мене в усякому добрі, а смерть зроби для мене полегшенням від усякого зла.", "Реформування релігії, цей світ і потойбічний світ — усі три.", "Повна дуа Пророка ﷺ."),
        "dua_musarrifal_qulub" to DuaText("Зверніть наші серця до вашої слухняності", "О Аллах, Перетворювач сердець, зверни наші серця до покори Тобі.", "Дуа, щоб зберегти серце твердим у покорі.", "Серця всіх людей між двома пальцями Всемилостивого."),
        "dua_jannah_nar" to DuaText("Просячи Джанні, притулку від вогню", "О Аллах, я прошу Тебе про рай і шукаю притулку в Тебе від вогню.", "Після ташаххуду або в будь-який час.", "Пророк ﷺ сказав: наші дуа також обертаються навколо цього."),
        "dua_khayri_kullih" to DuaText("Все добре, зараз і пізніше", "О Аллах, я прошу у Тебе всього доброго — негайного і відкладеного, того, що я знаю і чого я не знаю, — і я шукаю притулку в Тебе від усього зла — негайного і відкладеного, того, що я знаю, і чого я не знаю. О Аллах, я прошу Тебе про рай і про всі слова і вчинки, які наближають мене до нього, і я шукаю притулку в Тебе від Вогню і всіх слів і вчинків, які наближають мене до нього.", "Пророк ﷺ навчив цьому вичерпному дуа Айшу (RA) (частина дуа).", "Дуа, що збирає всі блага."),
        "dua_ihdini_saddidni" to DuaText("Веди мене і тримай мене у вертикальному положенні", "О Аллах, настав мене і тримай на правильному шляху.", "Пророк ﷺ навчив цьому Алі (RA).", "Думайте про керівництво як про те, щоб вас вели дорогою, а про садад як про прямолінійність стріли."),
        "dua_hubbaka" to DuaText("Прохання про любов Аллаха", "О Аллах, я прошу Твоєї любові, любові тих, хто любить Тебе, і вчинків, які приводять мене до Твоєї любові. О Аллах, зроби мені Твою любов дорожчою за мене самого, мою родину і холодну воду.", "Дуа Дауда (AS), пов’язана з Пророком ﷺ.", "Любов до Аллаха - найбільше багатство."),
        "dua_filal_khayrat" to DuaText("Творити добро і залишати зло", "О Аллах, я прошу Тебе дати мені можливість робити добрі справи, залишити погані вчинки і любити бідних, а Ти прости мене і помилуй мене. І коли Ти хочеш випробування для народу, візьми мене без випробування. Прошу Тебе про Твою любов, любов тих, хто любить Тебе, і любов до справ, які наближають мене до Твоєї любові.", "Аллах навчив цю дуа Пророку ﷺ уві сні.", "Пророк ﷺ сказав: це правда, тому вивчіть це і навчіть цьому."),
        "dua_bi_ilmikal_ghayb" to DuaText("Дозволь мені жити, поки життя хороше", "О Аллах, Твоїм знанням невидимого і Твоєю владою над творінням — збережи мене живим, доки Ти знаєш, що життя для мене краще, і візьми мене, коли Ти дізнаєшся, що смерть для мене краща. О Аллах, я прошу Тебе про страх перед Тобою наодинці та публічно, про слово істини в задоволенні та в гніві, і про помірність у бідності та багатстві.", "Молитовна дуа Аммара ібн Ясіра (RA) (вступна частина).", "Пророк ﷺ виголосив цю дуа в молитві."),
        "dua_ism_azam_mannan" to DuaText("Ісм-е-Азам: Аль-Маннан", "О Аллах, я прошу Тебе, бо Тобі належить вся хвала; немає бога, крім Тебе, Дарувальника милостей, Творця небес і землі. О Володарю величі й честі, о Вічноживий, о Хранитель!", "Пророк ﷺ сказав, що цей чоловік зробив дуа з Найвеличнішим Ім'ям Аллаха.", "Дуа, зроблена з цим Ім'ям, відповідає."),
        "dua_ism_azam_ahad_samad" to DuaText("Ісм-е-Азам: Аль-Ахад Ас-Самад", "О Аллах, я прошу Тебе, бо я свідчу, що Ти Аллах; немає бога, крім Тебе, Єдиного, Самодостатнього, Який не породжує і не народжується, і немає нікого, порівнянного з Ним.", "Пророк ﷺ сказав, що цей чоловік запитав Аллаха Його Найбільшим Ім'ям.", "Коли воно запитує, Він дає; коли воно кличе, Він відповідає."),
        "dua_thabbitni_hadiyan" to DuaText("Зроби мене твердим, керованим і провідником", "О Аллах, зроби мене твердим і зроби мене тим, хто направляє і ведеться.", "Пророк ﷺ зробив цю дуа для Джаріра (RA) (для себе скажіть «таббітні»).", "В оригінальній дуі для Джаріра (RA) використовуються слова «thabbit-hu»."),
        "dua_rabbighfir_tub_alayya" to DuaText("Прости мене і прийми моє каяття", "Мій Господи, прости мене і прийми моє каяття. Воістину, Ти — Той, хто приймає покаяння, Милосердний.", "Сто разів за один присід — практика Пророка ﷺ.", "Сподвижники порахували, що Пророк ﷺ сказав це сто разів за один присід."),
        "dua_rafiq_ala" to DuaText("Дуа вмираючого", "О Аллах, прости мене, помилуй мене і приєднай мене до Найвищого Сподвижника.", "Остання дуа Пророка ﷺ — для того, щоб хворий сказав сам.", "Пророк ﷺ виголосив цю дуа під час своєї смерті."),
        "dua_la_bas_tahur" to DuaText("Втішання хворих: очищення", "Ніякої шкоди; це очищення (від гріхів), якщо буде воля Аллаха.", "Втішати хворого при відвідуванні.", "Пророк ﷺ сказав це, відвідуючи хворих."),
        "dua_talqeen" to DuaText("Талкін для вмираючих", "Ніхто не гідний поклоніння, крім Аллаха.", "Прочитайте калиму біля вмираючої людини (не змушуйте її говорити це).", "Той, чиї останні слова будуть «Ля іляха іляллах», увійде в Рай (Абу Дауд 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("Замість бажання смерті", "О Аллах, збережи мене живим, поки мені буде краще жити, і візьми мене, коли мені буде краще смерть.", "Замість того, щоб бажати смерті в скруті.", "Пророк ﷺ заборонив бажати смерті і замість цього навчав цього."),
        "dua_for_one_i_cursed" to DuaText("Для когось, кого я скривдив словами", "О Аллах, будь-який віруючий, якого я образив, нехай стане для нього засобом близькості до Тебе в День Воскресіння.", "Для того, з ким ти говорив погано в гніві.", "Дуа Пророка ﷺ."),
        "dua_praising_someone" to DuaText("Коли когось хвалити", "Я вважаю те-то таким, і Аллах є його рахунком, і я не ручаюся за чиюсь чистоту перед Аллахом.", "Коли когось хвалити, а не перебільшувати.", "Пророк ﷺ навчав цього етикету хвали."),
        "dua_being_praised" to DuaText("Коли вас хвалять", "О Аллах, не бери мене до відповідальності за те, що вони говорять, і прости мене за те, чого вони не знають.", "Почувши похвалу — практика Компаньйона (RA).", "Спосіб уникнути зарозумілості, коли вас хвалять."),
        "dua_non_muslim_sneezes" to DuaText("Коли немусульманин чхає", "Нехай Аллах веде вас і налагоджує ваші справи.", "Коли немусульманин чхає і каже «Альхамдуліллах».", "Євреї чхали біля Пророка ﷺ, сподіваючись, що він скаже «Йархамукалла», і він говорив це."),
        "dua_reply_ahl_kitab_salam" to DuaText("Відповідь на Салам Людей Книги", "І на вас.", "Коли люди Книги вітають салам.", "Настанова Пророка ﷺ."),
        "dua_fasting_invited" to DuaText("При запрошенні під час посту", "Я постю.", "Коли запрошують у піст, або коли хтось з тобою посвариться.", "Якщо постник приймає запрошення, він повинен помолитися за господаря."),
        "dua_for_who_gave_drink" to DuaText("Для того, хто мене годував", "О Аллах, нагодуй того, хто годував мене, і напої того, хто напоїв мене.", "Для того, хто дає вам їсти чи пити.", "Пророк ﷺ зробив цю дуа для аль-Мікдада (RA)."),
        "dua_eid_greeting" to DuaText("Ід привітання", "Нехай Аллах прийме (добрі справи) від нас і від вас.", "Один одному в день Ід — звичай благородних сподвижників (RA).", "Сподвижники сказали це, коли зустрілися на Ід."),
        "dua_wedding_night" to DuaText("Для Нареченої Після Ніках", "О Аллах, я прошу Тебе про її добро і добро природи, якою Ти її створив, і я шукаю захисту в Тебе від її зла і зла природи, з якою Ти створив її.", "Після нікаху покласти руку на чоло дружини.", "Вчення Пророка ﷺ — благословення в шлюбі."),
        "dua_istisqa_ibadak" to DuaText("Напуйте своїх слуг і тварин", "О Аллах, дай води Своїм рабам і Твоїм тваринам, пошири Свою милість і оживи Твою мертву землю.", "Просити дощу (istisqa).", "Пророк ﷺ зробив цю дуа для дощу."),
        "dua_seeing_clouds" to DuaText("Бачити темні хмари", "О Аллах, я шукаю притулку в Тебе від його зла.", "Побачивши темні хмари на небі; якщо йде дощ, скажіть «Аллахумма сайібан нафі'а».", "Побачивши хмари, Пророк ﷺ залишав те, що він робив, і вимовляв цю дуа."),
        "dua_jamarat" to DuaText("Побивання камінням Джамарату", "Аллах є найбільший.", "З кожним кинутим камінчиком.", "Пророк ﷺ промовив такбір з кожним камінчиком, а потім після першого та другого джамри став обличчям до Кібли та зробив довгу дуа."),
        "dua_rabbi_ainni" to DuaText("Мій Господи, допоможи мені, а не проти мене", "Господи мій, допоможи мені і не допомагай іншим проти мене, даруй мені перемогу, а іншим не даруй перемоги наді мною, плануй для мене, а не плануй проти мене, настав мене і зроби для мене легким керівництво, і допоможи мені проти тих, хто кривдить мене.", "Повна дуа Пророка ﷺ (вступна частина).", "Дуа, яка збирає будь-яку допомогу в релігії та цьому світі."),
        "dua_ati_nafsi_taqwaha" to DuaText("Даруй моїй душі її такву", "О Аллах, даруй моїй душі її благочестя і очисти її, бо Ти найкращий, щоб очистити її. Ти його Охоронець і Господар.", "Для реформування та очищення себе.", "Пророк ﷺ використовував цю дуа."),
        "dua_iqsim_lana_khashyatik" to DuaText("Даруйте нам такий страх перед вами", "О Аллах, дай нам достатньо страху перед Тобою, щоб стати між нами і непокорою Тобі, достатньо покори, щоб привести нас до Твого Раю, і достатньо впевненості, щоб полегшити для нас лиха цього світу. Дозволь нам насолоджуватися нашим слухом, нашим зором і нашою силою, поки Ти зберігаєш нас живими і змушуєш їх пережити нас. Помстися тим, хто кривдить нас, допоможи нам проти наших ворогів, не дозволяй, щоб наше лихо було в нашій релігії, не роби цей світ нашою найбільшою турботою чи межею нашого знання, і не наставляй над нами тих, хто не викаже нам милосердя.", "Встаючи зі зборів — Пророк ﷺ рідко вставав без цієї дуа.", "Всеосяжний дуа для блага релігії, цього світу та потойбічного життя."),
        "dua_infani_bima_allamtani" to DuaText("Принеси мені користь тим, чого ти мене навчив", "О Аллах, дай мені користь тим, чому Ти навчив мене, навчи мене тому, що принесе мені користь, і примножи мені знання.", "Під час пошуку знань або перед навчанням.", "Дуа для корисних знань і дій відповідно до них."),
    )
}
